const assert=require('node:assert/strict');
const {quantity,available}=require('./src/quantity.cjs');
const {reserve}=require('./src/reserve.cjs');
const {release}=require('./src/release.cjs');
assert.equal(quantity(2),2);
for(const v of [0,-1,1.5,'2',NaN,Infinity,Number.MAX_SAFE_INTEGER+1]) assert.throws(()=>quantity(v),RangeError);
assert.equal(available(Object.create({a:9}),'a'),0);
assert.equal(available({a:0},'a'),0);
for(const v of [-1,1.5,'2',NaN]) assert.throws(()=>available({a:v},'a'),RangeError);
const stock=Object.freeze({a:5,b:2});
const items=Object.freeze([Object.freeze({sku:'a',quantity:2}),Object.freeze({sku:'a',quantity:1})]);
assert.deepEqual(reserve(stock,items),{a:2,b:2});
assert.deepEqual(stock,{a:5,b:2});
assert.deepEqual(release(stock,items),{a:8,b:2});
assert.deepEqual(release(stock,[{sku:'c',quantity:3}]),{a:5,b:2,c:3});
const mutable={a:5,b:1};
assert.throws(()=>reserve(mutable,[{sku:'a',quantity:2},{sku:'b',quantity:2}]),RangeError);
assert.deepEqual(mutable,{a:5,b:1});
assert.throws(()=>reserve(stock,[{sku:'a',quantity:3},{sku:'a',quantity:3}]),RangeError);
assert.throws(()=>reserve(stock,[{sku:'absent',quantity:1}]),RangeError);
for(const fn of [reserve,release]){
 assert.throws(()=>fn(stock,[{sku:'a',quantity:0}]),RangeError);
 assert.throws(()=>fn({a:-1},[{sku:'a',quantity:1}]),RangeError);
 assert.deepEqual(fn(stock,[]),stock);
 assert.notEqual(fn(stock,[]),stock);
}
assert.throws(()=>release({a:Number.MAX_SAFE_INTEGER},[{sku:'a',quantity:1}]),RangeError);
console.log('protected stock acceptance passed');
